import test from 'ava'

import { Fib, Fib2, Fib3, shutdownRuntime } from '../index.cjs'

type IteratorWithHelpers<T> = Iterator<T> & {
  [Symbol.iterator](): IteratorWithHelpers<T>
  take(limit: number): { toArray(): T[] }
}

test.after(() => {
  shutdownRuntime()
})

for (const [index, factory] of [
  () => new Fib(),
  () => Fib2.create(0),
  () => new Fib3(0, 1),
].entries()) {
  test(`should be able to stop a generator #${index}`, (t) => {
    const fib = factory()
    const gen = fib[Symbol.iterator]
    t.is(typeof gen, 'function')
    const iterator = gen()
    t.deepEqual(iterator.next(), {
      done: false,
      value: 1,
    })
    iterator.next()
    iterator.next()
    iterator.next()
    iterator.next()
    t.deepEqual(iterator.next(), {
      done: false,
      value: 8,
    })
    t.deepEqual(iterator.return?.(), {
      done: true,
    })
    t.deepEqual(iterator.next(), {
      done: true,
    })
  })

  test(`should be able to throw to generator #${index}`, (t) => {
    const fib = factory()
    const gen = fib[Symbol.iterator]
    t.is(typeof gen, 'function')
    const iterator = gen()
    t.deepEqual(iterator.next(), {
      done: false,
      value: 1,
    })
    iterator.next()
    iterator.next()
    iterator.next()
    iterator.next()
    t.deepEqual(iterator.next(), {
      done: false,
      value: 8,
    })
    t.throws(() => iterator.throw!(new Error()))
    t.deepEqual(iterator.next(), {
      done: true,
    })
  })

  test(`should inherit Iterator helpers #${index}`, (t) => {
    const iteratorConstructor = (
      globalThis as typeof globalThis & {
        Iterator?: Function & { prototype: object }
      }
    ).Iterator
    if (typeof iteratorConstructor !== 'function') {
      t.pass()
      return
    }

    const iterator = factory()[Symbol.iterator]() as IteratorWithHelpers<number>
    t.true(iteratorConstructor.prototype.isPrototypeOf(iterator))
    t.is(iterator[Symbol.iterator](), iterator)
    t.deepEqual(iterator.take(5).toArray(), [1, 1, 2, 3, 5])
  })
}
